alter table schedule_compute_workers add column if not exists connection_mode text not null default 'PULL',add column if not exists endpoint_url text,add column if not exists software_version text,add column if not exists cpu_threads smallint,add column if not exists gpu_model text,add column if not exists gpu_memory_mb integer,add column if not exists lease_seconds integer not null default 120;
alter table schedule_solve_attempts add column if not exists claimed_at timestamptz,add column if not exists lease_until timestamptz,add column if not exists result_payload jsonb not null default '{}';
alter table teacher_unavailability add column if not exists source text not null default 'manual',add column if not exists note text;
create index if not exists idx_solve_attempt_worker_status on schedule_solve_attempts(worker_id,status,lease_until);
create or replace function preserve_manual_schedule_v1(p_preserve boolean default true) returns integer language plpgsql security definer set search_path=public as $$declare n int;begin perform open_permission_context('schedule.edit');if p_preserve then update teacher_schedule set locked=true,updated_at=now() where institution_code=current_tenant_code() and active and source_kind='manual' and not locked;get diagnostics n=row_count;else n:=0;end if;return n;end$$;
create or replace function set_teacher_slot_unavailable_v1(p_teacher_id uuid,p_weekday smallint,p_period smallint,p_blocked boolean,p_source text default 'manual',p_note text default null) returns boolean language plpgsql security definer set search_path=public as $$begin perform open_permission_context('schedule.rules');if p_blocked then insert into teacher_unavailability(teacher_id,weekday,period,reason,active,institution_code,source,note,approved_by,approved_at) values(p_teacher_id,p_weekday,p_period,coalesce(nullif(p_note,''),'Kullanıcı tarafından kapatıldı'),true,current_tenant_code(),coalesce(nullif(p_source,''),'manual'),p_note,auth.uid(),now()) on conflict do nothing;else update teacher_unavailability set active=false where institution_code=current_tenant_code() and teacher_id=p_teacher_id and weekday=p_weekday and period=p_period and active;end if;return true;end$$;
create or replace function worker_claim_schedule_attempt_v1(p_worker_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare w schedule_compute_workers%rowtype;a schedule_solve_attempts%rowtype;j schedule_solve_jobs%rowtype;payload jsonb;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select * into w from schedule_compute_workers where worker_key=p_worker_key and active and health in('HEALTHY','DEGRADED') for update;if not found then return null;end if;select a0.* into a from schedule_solve_attempts a0 join schedule_solve_jobs j0 on j0.id=a0.job_id where a0.worker_id=w.id and a0.status in('PLANNED','RUNNING') and (a0.status='PLANNED' or a0.lease_until<now()) and j0.status in('QUEUED','RUNNING') order by j0.created_at,a0.attempt_no for update of a0 skip locked limit 1;if not found then update schedule_compute_workers set last_heartbeat=now(),updated_at=now() where id=w.id;return null;end if;select * into j from schedule_solve_jobs where id=a.job_id;update schedule_solve_attempts set status='RUNNING',claimed_at=coalesce(claimed_at,now()),started_at=coalesce(started_at,now()),lease_until=now()+make_interval(secs=>w.lease_seconds) where id=a.id;update schedule_solve_jobs set status='RUNNING',started_at=coalesce(started_at,now()) where id=j.id;update schedule_compute_workers set last_heartbeat=now(),current_load=least(1,current_load+1.0/greatest(max_parallel,1)),updated_at=now() where id=w.id;select jsonb_build_object('attempt_id',a.id,'job_id',j.id,'tenant',j.institution_code,'seed',a.seed,'quality_target',j.quality_target,'config',j.config,'problem',jsonb_build_object('time_profile',(select to_jsonb(t) from schedule_time_profiles t where t.institution_code=j.institution_code and t.active order by t.updated_at desc limit 1),'assignments',(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',ta.id,'teacher_id',ta.teacher_id,'assigned_hours',ta.assigned_hours,'requirement_id',r.id,'class_id',r.class_id,'course_id',r.course_id,'weekly_hours',r.weekly_hours,'class_name',c.class_name,'course_name',cc.name)), '[]'::jsonb) from teacher_course_assignments ta join class_course_requirements r on r.id=ta.class_course_requirement_id join school_classes c on c.id=r.class_id join course_catalog cc on cc.id=r.course_id where ta.institution_code=j.institution_code),'locked_rows',(select coalesce(jsonb_agg(to_jsonb(ts)),'[]'::jsonb) from teacher_schedule ts where ts.institution_code=j.institution_code and ts.active and ts.locked),'teacher_unavailability',(select coalesce(jsonb_agg(to_jsonb(u)),'[]'::jsonb) from teacher_unavailability u where u.institution_code=j.institution_code and u.active),'teacher_constraints',(select coalesce(jsonb_agg(to_jsonb(tc)),'[]'::jsonb) from teacher_schedule_constraints tc where tc.institution_code=j.institution_code),'course_rules',(select coalesce(jsonb_agg(to_jsonb(cr)),'[]'::jsonb) from course_schedule_rules cr where cr.institution_code=j.institution_code and cr.active),'overrides',(select coalesce(jsonb_agg(to_jsonb(o)),'[]'::jsonb) from schedule_rule_overrides o where o.institution_code=j.institution_code and o.active))) into payload;return payload;end$$;
create or replace function worker_heartbeat_schedule_v1(p_worker_key text,p_load numeric default null,p_latency_ms integer default null) returns boolean language plpgsql security definer set search_path=public as $$begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;update schedule_compute_workers set health='HEALTHY',last_heartbeat=now(),current_load=coalesce(p_load,current_load),avg_latency_ms=coalesce(p_latency_ms,avg_latency_ms),updated_at=now() where worker_key=p_worker_key and active;return found;end$$;
create or replace function worker_complete_schedule_attempt_v1(p_worker_key text,p_attempt_id uuid,p_result jsonb,p_duration_ms integer default null,p_error text default null) returns boolean language plpgsql security definer set search_path=public as $$declare w uuid;j uuid;remaining int;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select id into w from schedule_compute_workers where worker_key=p_worker_key and active;if w is null then raise exception 'WORKER_NOT_FOUND';end if;update schedule_solve_attempts set status=case when p_error is null then 'COMPLETED' else 'FAILED' end,result_payload=coalesce(p_result,'{}'),diagnostics=diagnostics||case when p_error is null then '{}'::jsonb else jsonb_build_object('error',p_error) end,duration_ms=p_duration_ms,finished_at=now(),lease_until=null where id=p_attempt_id and worker_id=w returning job_id into j;if j is null then raise exception 'ATTEMPT_NOT_FOUND';end if;update schedule_compute_workers set current_load=greatest(0,current_load-1.0/greatest(max_parallel,1)),last_heartbeat=now(),updated_at=now() where id=w;select count(*) into remaining from schedule_solve_attempts where job_id=j and status in('PLANNED','RUNNING');if remaining=0 then update schedule_solve_jobs set status=case when exists(select 1 from schedule_solve_attempts where job_id=j and status='COMPLETED') then 'COMPLETED' else 'FAILED' end,finished_at=now() where id=j;end if;return true;end$$;